    Bug 1961489 - fix Empty string passed to getElementById() warnings due to missing row ids. r=freaktechnik


    Error can easily be seen by running comm/mail/test/browser/message-header/browser_messageHeader.js

    It seems to be caused as a side-effect of accessing "aria-activedescendant" for ids not set.
    That probably had some (not so nice) accessibility implications.

    Differential Revision: https://phabricator.services.mozilla.com/D249998

diff --git a/mail/base/content/widgets/tree-view.mjs b/mail/base/content/widgets/tree-view.mjs
index a57bf39d18b..e45fc76eefa 100644
--- a/mail/base/content/widgets/tree-view.mjs
+++ b/mail/base/content/widgets/tree-view.mjs
@@ -1275,6 +1275,8 @@ export class TreeView extends HTMLElement {
     row.setAttribute("aria-setsize", this._view.rowCount);
     row.style.height = `${this._rowElementClass.ROW_HEIGHT}px`;
     row.index = index;
+    row.id = `${this.id}-row${index}`; // See _fillRow()
+
     if (this._selection?.isSelected(index)) {
       row.selected = true;
     }
